<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { Search, Refresh } from '@element-plus/icons-vue'
import { authAndAdminApi, roleOptions, type SystemUser, type UserQuery, type UserUpdate } from '@/api/authAndAdminApi'
import { formatTime } from '@/api/types'
import { useAuthStore } from '@/stores/authStore'
const auth = useAuthStore(), rows = ref<SystemUser[]>([]), loading = ref(false), failed = ref(false), total = ref(0)
const query = reactive<UserQuery>({ keyword: '', deptClass: '', pageNum: 1, pageSize: 10 })
const editing = ref<SystemUser>(), dialog = ref(false), saving = ref(false), form = ref<FormInstance>()
const draft = reactive<UserUpdate>({}), rules: FormRules = { roleType: [{ required: true, message: '请选择角色' }], tokenQuota: [{ required: true, message: '请输入剩余算力' }], status: [{ required: true, message: '请选择账号状态' }] }
let requestId = 0
async function load(reset = false) {
  if (reset) query.pageNum = 1
  if (query.minQuota != null && query.maxQuota != null && query.minQuota > query.maxQuota) { ElMessage.warning('算力下限不能大于上限'); return }
  const id = ++requestId; loading.value = true; failed.value = false
  try { const page = await authAndAdminApi.users(query); if (id === requestId) { rows.value = page.records; total.value = page.total } }
  catch { if (id === requestId) failed.value = true } finally { if (id === requestId) loading.value = false }
}
function reset() { Object.assign(query, { keyword: '', roleType: undefined, deptClass: '', status: undefined, minQuota: undefined, maxQuota: undefined, pageNum: 1 }); void load() }
function edit(user: SystemUser) { editing.value = user; Object.assign(draft, { roleType: user.roleType, deptClass: user.deptClass, status: user.status, tokenQuota: user.tokenQuota, resetPassword: false }); dialog.value = true }
async function save() {
  if (!editing.value || !(await form.value?.validate().catch(() => false))) return
  if (draft.resetPassword) {
    const confirmed = await ElMessageBox.confirm('确认将该用户的密码重置为 123456？', '重置密码', { type: 'warning', confirmButtonText: '确认重置', cancelButtonText: '取消' }).then(() => true).catch(() => false)
    if (!confirmed) return
  }
  saving.value = true
  try { const updated = await authAndAdminApi.updateUser(editing.value.id, draft); if (updated.id === auth.user?.id) await auth.loadUser(); dialog.value = false; ElMessage.success('账号权限与算力已更新'); await load() }
  catch { /* Server error is displayed by the request interceptor. */ } finally { saving.value = false }
}
onMounted(() => { void load() })
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">IDENTITY & ACCESS</p><h1>用户与权限</h1><p class="subtitle">管理师生身份、账号状态与可用算力，支持组合条件检索。</p></div><el-tag effect="plain">共 {{ total }} 个账号</el-tag></div><div class="panel list-panel"><el-form class="search-form user-search" inline @submit.prevent="load(true)"><el-form-item label="账号 / 姓名"><el-input v-model="query.keyword" placeholder="关键词" clearable :prefix-icon="Search" maxlength="64"/></el-form-item><el-form-item label="角色"><el-select v-model="query.roleType" clearable placeholder="全部角色"><el-option v-for="r in roleOptions" :key="r.value" :value="r.value" :label="r.label"/></el-select></el-form-item><el-form-item label="院系 / 班级"><el-input v-model="query.deptClass" clearable placeholder="院系或班级" maxlength="100"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" placeholder="全部状态" clearable><el-option :value="1" label="正常"/><el-option :value="0" label="禁用"/></el-select></el-form-item><el-form-item label="剩余算力"><el-input-number v-model="query.minQuota" :min="0" :max="2147483647" :controls="false" placeholder="最低"/><span class="range-separator">—</span><el-input-number v-model="query.maxQuota" :min="0" :max="2147483647" :controls="false" placeholder="最高"/></el-form-item><el-form-item><el-button type="primary" :icon="Search" native-type="submit">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form><el-alert v-if="failed" title="用户列表加载失败，请重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="暂无符合条件的用户"><el-table-column label="用户" min-width="190"><template #default="{ row }"><div class="user-identity"><span class="avatar">{{ row.realName.slice(0,1) }}</span><div><strong>{{ row.realName }}</strong><small>{{ row.username }}</small></div></div></template></el-table-column><el-table-column label="角色" width="110"><template #default="{ row }"><el-tag effect="plain" :type="row.roleType === 'ADMIN' ? 'warning' : row.roleType === 'TEACHER' ? 'primary' : 'info'">{{ roleOptions.find(r => r.value === row.roleType)?.label }}</el-tag></template></el-table-column><el-table-column prop="deptClass" label="院系 / 班级" min-width="160" show-overflow-tooltip/><el-table-column label="剩余算力" min-width="120" align="right"><template #default="{ row }">{{ row.tokenQuota.toLocaleString() }}</template></el-table-column><el-table-column label="累计消耗" min-width="120" align="right"><template #default="{ row }">{{ row.tokenUsed.toLocaleString() }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'danger'" size="small">{{ row.status ? '正常' : '禁用' }}</el-tag></template></el-table-column><el-table-column label="最近登录" min-width="175"><template #default="{ row }">{{ formatTime(row.lastLoginAt) }}</template></el-table-column><el-table-column label="操作" fixed="right" width="150"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">管理 / 充值</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ total }} 个账号</span><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="sizes,prev,pager,next" @current-change="load()" @size-change="load(true)"/></div></div><el-dialog v-model="dialog" :title="`管理账号 · ${editing?.realName ?? ''}`" width="500px" destroy-on-close :close-on-click-modal="!saving"><el-form ref="form" :model="draft" :rules="rules" label-position="top"><el-form-item label="角色" prop="roleType"><el-select v-model="draft.roleType" :disabled="editing?.id === auth.user?.id"><el-option v-for="r in roleOptions" :key="r.value" :label="r.label" :value="r.value"/></el-select></el-form-item><el-form-item label="院系 / 班级"><el-input v-model="draft.deptClass" maxlength="100"/></el-form-item><el-form-item label="账号状态" prop="status"><el-switch v-model="draft.status" :active-value="1" :inactive-value="0" active-text="正常" inactive-text="禁用" :disabled="editing?.id === auth.user?.id"/></el-form-item><el-form-item label="设置剩余算力额度" prop="tokenQuota"><el-input-number v-model="draft.tokenQuota" :min="0" :max="2147483647" :precision="0"/><el-button text type="primary" @click="draft.tokenQuota = Math.min(2147483647, (draft.tokenQuota ?? 0) + 50000)">+50,000 充值</el-button></el-form-item><p class="muted">保存后将剩余额度设置为上方数值，累计消耗不受影响。</p><el-form-item><el-checkbox v-model="draft.resetPassword">重置密码为 123456</el-checkbox></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存更改</el-button></template></el-dialog></section></template>
<style scoped>.user-search{padding-top:24px}.user-search .el-select{width:140px}.user-search .el-input-number{width:115px}.user-identity{display:flex;align-items:center;gap:10px}.user-identity strong{display:block;font-size:13px;font-weight:600}.user-identity small{display:block;color:#96a198;font-size:11px;margin-top:4px}.el-dialog .el-select{width:100%}</style>
